CREATE TABLE public.field_report_items (
    id bigint NOT NULL,
    category character varying(255),
    description character varying(1000) NOT NULL,
    facility_id bigint,
    facility_name character varying(255),
    health_centre_id bigint,
    health_centre_name character varying(255),
    item_type character varying(30) NOT NULL,
    last_synced_at timestamp(6) without time zone,
    medicine_id bigint,
    medicine_name character varying(255),
    priority character varying(10),
    quantity integer,
    routing_message character varying(500),
    routing_status character varying(10),
    target_id bigint,
    target_path character varying(255),
    target_reference character varying(255),
    target_service character varying(255),
    target_status character varying(255),
    water_source_id bigint,
    water_source_name character varying(255),
    report_id bigint,
    CONSTRAINT field_report_items_item_type_check CHECK (((item_type)::text = ANY ((ARRAY['SANITATION_MAINTENANCE'::character varying, 'SANITATION_COMPLAINT'::character varying, 'MEDICINE_SHORTAGE'::character varying, 'WATER_ISSUE'::character varying])::text[]))),
    CONSTRAINT field_report_items_priority_check CHECK (((priority)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT field_report_items_routing_status_check CHECK (((routing_status)::text = ANY ((ARRAY['ROUTED'::character varying, 'FAILED'::character varying])::text[])))
);
ALTER TABLE public.field_report_items ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.field_report_items_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.field_reports (
    id bigint NOT NULL,
