    report_date date,
    report_number character varying(20),
    reported_by character varying(255),
    reporter_role character varying(255),
    summary character varying(1000),
    village character varying(255) NOT NULL
);
ALTER TABLE public.field_reports ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.field_reports_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
